    @Override
    public Builder image(final PagerDutyImageRef image) {
      if (images.isEmpty()) {
        images = List.of(image);
        return this;
      } else if (images.size() == 1) {
        images = new ArrayList<>(images);
      }
      images.add(image);
      return this;
    }
